import React, { useState, useEffect } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { Grid, Button, Typography, MenuItem, Card, Accordion, AccordionSummary, AccordionDetails, IconButton, Menu, Box, Dialog, DialogActions, DialogContent, DialogContentText, DialogTitle, TextField, Link, Divider } from '@mui/material';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import MoreVertIcon from '@mui/icons-material/MoreVert';
import { DemoContainer } from '@mui/x-date-pickers/internals/demo';
import { LocalizationProvider } from '@mui/x-date-pickers/LocalizationProvider';
import { AdapterDayjs } from '@mui/x-date-pickers/AdapterDayjs';

import dayjs from 'dayjs';
import 'dayjs/locale/en-gb';
import { DatePicker } from '@mui/x-date-pickers/DatePicker';
import InputLabel from '@mui/material/InputLabel';
import FormControl from '@mui/material/FormControl';
import Select from '@mui/material/Select';
import Iconify from '../../components/iconify';
import { axios } from '../../utils/axios';
import { IMAGE_URL } from '../../utils/config';
import CountryCode from '../../CountryCode'
import { useMyContext } from '../provider';
import PhoneLengthByCountry from '../../PhoneLengthByCountry';
import GenerateToastConfig from '../../components/toast-config/GenerateToastConfig';
import GoBackButton from '../../components/goBackButton/GoBackButton';
import ImageUpload from '../../components/input/imageUpload';
import InputField from '../../components/input/inputField';
import DateFormat from '../../components/dayjsFormat/DateFormat';
import { replaceStarsInEmailAddress, replaceStarsInMobileNumber } from "../../utils/sensitive"

import useResponsive from '../../hooks/useResponsive';

const ITEM_HEIGHT = 48;
const ITEM_PADDING_TOP = 8;
const MenuProps = {
  PaperProps: {
    style: {
      maxHeight: ITEM_HEIGHT * 4.5 + ITEM_PADDING_TOP,
      width: 250,
    },
  },
};

function EditUser() {
  const location = useLocation();
  const navigate = useNavigate();
  const [details, setDetails] = useState("")
  const [fname, setFname] = useState('');
  const [lname, setLname] = useState('');
  const [eMails, setEMails] = useState('');
  const [phoneCodes, setPhoneCodes] = useState('');
  const [phoneNumber, setPhoneNumber] = useState('');
  const [dobs, setDobs] = useState('');
  const [profilePic, setProfilePic] = useState('');
  const [images, setImg] = useState("")
  const [emailError, setEmailError] = useState('');
  const [isAbove18, setIsAbove18] = useState(true);
  const [error, setError] = useState('');
  const [phoneCodeError, setPhoneCodeError] = useState('');
  const [genders, setGenders] = useState(details?.gender || '');
  const [selectedCountry, setSelectedCountry] = useState(null);
  const { documentsMode, i18 } = useMyContext();
  const queryParams = new URLSearchParams(location.search);
  const id = queryParams.get("userId")
  const isMobile = useResponsive("down", "sm")
  const isDisableButton = !isAbove18 || error || phoneCodeError || emailError;

  const [documents, setDocuments] = useState([])
  const [anchorEl, setAnchorEl] = useState(null);
  const [selectedAccordion, setSelectedAccordion] = useState(null);
  const [openModal, setOpenModal] = useState(false);
  const [date, setDate] = useState(null);
  const [imageValues, setImageValues] = useState({});
  const [textValues, setTextValues] = useState({});

  // const validatePancardNumber = (value) => {
  //   // Regular expression to match PAN Card number format
  //   const regex = /^[A-Z]{5}[0-9]{4}[A-Z]$/;

  //   // Check if the input value matches the regex pattern
  //   const isValid = regex.test(value);

  //   setIsValidPancard(isValid);
  //   return isValid;
  // };

  // const handleInputChange = (e) => {
  //   const inputValue = e.target.value.toUpperCase(); // Convert input to uppercase
  //   setPancardNumber(inputValue);
  //   validatePancardNumber(inputValue);
  // };

  const getTranslation = (key) => {
    const keyValue = key && key.replace(/\s+/g, '').toUpperCase();
    const sectionLabel = i18.ACCOUNTSTITLE && i18.ACCOUNTSTITLE[keyValue];
    return sectionLabel || key;
  };



  const backtouser = () => {
    navigate('/dashboard/user');
  };

  const handleUploadedFile = (event) => {
    const file = event.target.files[0];
    setImg(file)
  }

  const getUserDetails = async () => {
    try {
      const res = await axios.get(`module/auth/user/${id}`);
      if (res.status === 200) {
        setDetails(res?.data?.data?.userDetail)
        setGenders(res?.data?.data?.userDetail?.gender)
        setFname(res?.data?.data?.userDetail?.firstname)
        setLname(res?.data?.data?.userDetail?.lastname)
        setEMails(res?.data?.data?.userDetail?.email)
        setPhoneNumber(res?.data?.data?.userDetail?.phone)
        setPhoneCodes(res?.data?.data?.userDetail?.phoneCode)
        setImg(res?.data?.data?.userDetail?.profileImage)
      }
    } catch (err) {
      console.error(err);
    }
  }

  useEffect(() => {
    getUserDetails()
    getDocumentsDetails();
  }, [])

  const EditUserApi = async () => {
    const updatedValues = new FormData();
    updatedValues.append('file', profilePic || details?.profileImage);
    updatedValues.append('phone', phoneNumber || details?.phone);
    updatedValues.append('phoneCode', phoneCodes || details?.phoneCode);
    updatedValues.append('email', eMails || details?.email);
    updatedValues.append('dob', dobs || details?.dob);
    updatedValues.append('firstname', fname || details?.firstname);
    updatedValues.append('lastname', lname || details?.lastname);
    updatedValues.append('gender', genders || details?.gender);
    updatedValues.append('file', images);
    try {
      const res = await axios.put(`module/auth/user/${id}`, updatedValues);
      if (res.status === 200) {
        GenerateToastConfig(res.data.message, 'success');
        navigate('/dashboard/user');
      } else {
        GenerateToastConfig(res.data.message);
      }
    } catch (err) {
      GenerateToastConfig(err?.response?.data?.message);
    }
  };
  const today = dayjs();
  const startOfCurrentYear = today.startOf('year');
  const endOfPreviousYear = startOfCurrentYear.subtract(1, 'year').endOf('year');

  const handleDateChange = (newValue) => {
    setDobs(newValue);
    const currentDate = dayjs();
    const age = currentDate.diff(newValue, 'year');
    setIsAbove18(age >= 18);
  };

  const getMaxDate = () => {
    // If today is within the current year, set maxDate to December 31 of the previous year
    return today.isAfter(startOfCurrentYear) || today.isSame(startOfCurrentYear, 'year')
      ? endOfPreviousYear
      : today;
  };

  // const getMaxDate = () => {
  //   // If today is within the current year, set maxDate to December 31 of the previous year
  //   return today.isAfter(startOfCurrentYear) || today.isSame(startOfCurrentYear, 'year')
  //     ? endOfPreviousYear
  //     : today;
  // };

  const userVerify = async (ids, boolean) => {
    try {
      const res = await axios.put(
        `module/auth/user/VerifyAndActiveStatus/${ids}`,
        new URLSearchParams({ verify: boolean })
      );
      if (res.status === 200) {
        GenerateToastConfig(res.data.message, 'info');
        navigate('/dashboard/user');
      } else {
        GenerateToastConfig(res.data.message);
      }
    } catch (err) {

      GenerateToastConfig(err?.response?.data?.message);
    }
  };

  const userActive = async (ids, boolean) => {
    try {
      const res = await axios.put(
        `module/auth/user/VerifyAndActiveStatus/${ids}`,
        new URLSearchParams({ active: boolean })
      );

      if (res.status === 200) {
        GenerateToastConfig(res.data.message, 'info');
        navigate('/dashboard/user');
      } else {
        GenerateToastConfig(res.data.message);
      }
    } catch (err) {
      GenerateToastConfig(err?.response?.data?.message);
    }
  };

  const handleMailChange = (e) => {
    const emailInput = e.target.value;
    setEMails(emailInput);

    if (!/[a-z0-9]+@[^\s@]+\.[a-z]{3}$/.test(emailInput)) {
      setEmailError('Invalid email format');
    } else if (/[!#$%^&*()_+|[\]{};:'"<>]/.test(emailInput)) {
      setEmailError('Invalid email format');
    } else {
      setEmailError('');
    }
  };

  const handleCountryChange = (event) => {
    const country = CountryCode.find(c => c.dial_code === event.target.value);
    setSelectedCountry(country);
    setPhoneCodes(country.dial_code);
    setPhoneNumber('');
  };

  const handlePhoneNumberChange = (event) => {
    const { value } = event.target;
    if (/^\d*$/.test(value)) { // Allow only digits
      setPhoneNumber(value);
      if (selectedCountry && value.length !== PhoneLengthByCountry[selectedCountry.code]) {
        setError('Invalid Phone Number')
      } else {
        setError('');
      }
    }
  };

  const getPhoneNumberInput = () => {
    if (selectedCountry) {
      const maxLength = PhoneLengthByCountry[selectedCountry.code];
      return (
        <InputField
          label={i18?.ACCOUNTSTITLE?.PHONE_NUMBER || "Phone Number"}
          sx={{
            margin: '10px 0px',
            width: '100%',
            '& .MuiInputBase-input.MuiOutlinedInput-input': {
              padding: '10.5px 14px'
            }
          }}
          inputProps={{ inputMode: 'numeric', pattern: '[0-9]*', maxLength }}
          value={phoneNumber}
          error={!!error}
          helperText={error}
          onChange={handlePhoneNumberChange}
          required
        />
      );
    }
    return (
      <InputField
        label={i18?.ACCOUNTSTITLE?.PHONE_NUMBER || "Phone Number"}
        sx={{
          margin: '10px 0px',
          width: '100%',
          '& .MuiInputBase-input.MuiOutlinedInput-input': {
            padding: '10.5px 14px'
          }
        }}
        value={phoneNumber ? replaceStarsInMobileNumber(phoneNumber, "1", details?.phone) : ""}
        onChange={handlePhoneNumberChange}
        disabled
      />
    )
  };

  const getDocumentsDetails = async () => {
    try {
      const res = await axios.get(`/module/document/user/${id}`)
      if (res.status === 200) {
        setDocuments(res?.data?.data?.documents)
      }
    } catch (error) {
      console.error(error);
    }
  }

  const handleMenuOpen = (event, doc) => {
    if (event.stopPropagation) {
      event.stopPropagation();
    }
    setSelectedAccordion(doc);
    setAnchorEl(event.currentTarget);
  };

  const handleMenuClose = () => {
    setAnchorEl(null);
  };

  const handleActionDocuments = () => {
    setOpenModal(true);
    setAnchorEl(null);
    handleMenuClose();
  };

  const handleModalClose = () => {
    setOpenModal(false);
  };

  const handleFileChange = (e, indexName) => {
    const file = e.target.files[0];
    if (indexName.includes('Image')) {
      setImageValues((prevImages) => ({ ...prevImages, [indexName]: file, }));
    } else {
      setTextValues((prevValues) => ({ ...prevValues, [indexName]: file, }));
    }
  };

  const handleDocumentDateChange = (newValue, indexName) => {
    // Use newValue.format('YYYY-MM-DD'): This formats the date to a string without any time component, avoiding timezone issues.
    const formattedDate = newValue.format('YYYY-MM-DD');
    setDate(newValue); // Update state with the selected date
    setTextValues((prevValues) => ({ ...prevValues, [indexName]: formattedDate }));
  };

  const handleInputChange = (e, indexName) => {
    const { value } = e.target;
    setTextValues((prevValues) => ({ ...prevValues, [indexName]: value, })
    );
  };

  const handleModalSave = async (fieldName) => {
    try {
      const formData = new FormData();
      formData.append('fieldName', fieldName);

      selectedAccordion.fields.forEach((field) => {
        const { indexName, type } = field;

        if (indexName.includes('Image')) {
          const file = imageValues[indexName];
          if (file) {
            formData.append(indexName, file);
          }
        } else if (type === 'date') {
          const date = textValues[indexName];
          if (date) {
            formData.append(indexName, date);
          }
        } else {
          const value = textValues[indexName] || '';
          formData.append(indexName, value);
        }
      });

      const res = await axios.post(`/module/document/user/${id}`, formData);
      if (res.status === 200) {
        GenerateToastConfig(res.data.message, 'success')
        getDocumentsDetails() // FOR LIVE UPDATES
      }
      handleModalClose();
    } catch (error) {
      console.error('Error saving data:', error);
      GenerateToastConfig("Please provide the details")
    }
  };

  const handleVerifyDocuments = async (userId, name, status) => {
    const data = { userId, name, status };
    try {
      const res = await axios.patch(`/module/document/updateStatus`, data);
      if (res.status === 200) {
        GenerateToastConfig(res.data.message, 'success')
        getDocumentsDetails() // FOR LIVE UPDATES
      }
    } catch (error) {
      console.error(error);
    }
    handleMenuClose();
  };
  return (
    <>
      {/* <Grid container sx={{ padding: '10px 0px' }}>
        <Grid container item justifyContent="space-between" alignItems="center" sx={{ marginRight: '10px' }}>
          <Box sx={{ display: "flex", alignItems: "center" }}>
            <Box
              sx={{
                width: '37px',
                height: '37px',
                background: '#FF5A60',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                borderRadius: '50%',
                cursor: 'pointer'
              }}
              onClick={backtouser} >
              <Iconify icon={"mdi:arrow-left"} width={24} height={24} color="white" />
            </Box>
            {details.firstname ?
              <Typography variant="h6" gutterBottom sx={{ margin: '0px 0px 0px 10px', paddingBottom: '0px' }}>
                {details.firstname}
                {details.lastname}'s  {i18?.ACCOUNTSTITLE?.PROFILE || "Profile"}
              </Typography>
              :
              <Typography variant="h6" gutterBottom sx={{ margin: '0px 0px 0px 10px', paddingBottom: '0px' }}>
                {i18?.ACCOUNTSTITLE?.USER_PROFILE || "User Profile"}
              </Typography>
            }
          </Box>
        </Grid>
      </Grid> */}
      <Card sx={{ padding: '20px 10px', margin: '10px 0px' }}>
        <Grid container sx={{ borderBottom: '1px solid #dbe0e4', padding: '10px 0px' }}>
          <Grid container item justifyContent="space-between" alignItems="center" sx={{ marginRight: '10px' }}>
            {details.firstname ?
              <Typography variant="h6" gutterBottom sx={{ margin: '0px 0px 0px 10px', paddingBottom: '0px' }}>
                {details.firstname}
                {details.lastname}'s  {i18?.ACCOUNTSTITLE?.PROFILE || "Profile"}
              </Typography>
              :
              <Typography variant="h6" gutterBottom sx={{ margin: '0px 0px 0px 10px', paddingBottom: '0px' }}>
                {i18?.ACCOUNTSTITLE?.USER_PROFILE || "User Profile"}
              </Typography>
            }
            <GoBackButton
              label={i18?.ACCOUNTSTITLE?.GO_BACK || "Go Back"}
              onClick={backtouser}
              icon="icon-park-twotone:back"
            />
          </Grid>
        </Grid>
        <Grid container={!isMobile} sx={{ marginTop: '10px' }}>
          <Grid item xs={6} sx={{ padding: '0px 5px' }}>
            <InputField
              label={i18?.ACCOUNTSTITLE?.FIRST_NAME || "First Name"}
              sx={{
                margin: '10px 0px',
                width: '100%',
                '& .MuiInputBase-input.MuiOutlinedInput-input': {
                  padding: '10.5px 14px'
                }
              }}
              name="FirstName"
              value={fname}
              onChange={(e) => {
                const textInput = e.target.value;
                // Use a regular expression to check for alphabetic characters only
                const validTextInput = textInput.replace(/[^a-zA-Z]/g, '');
                setFname(validTextInput);
              }}
              onKeyDown={(e) => {
                // Prevent typing numbers and special characters by capturing keydown events
                if (!/^[a-zA-Z]*$/.test(e.key)) {
                  e.preventDefault();
                }
              }}
            />
          </Grid>
          <Grid item xs={6} sx={{ padding: '0px 5px' }}>
            <InputField
              label={i18?.ACCOUNTSTITLE?.LAST_NAME || "Last Name"}
              sx={{
                margin: '10px 0px',
                width: '100%',
                '& .MuiInputBase-input.MuiOutlinedInput-input': {
                  padding: '10.5px 14px'
                }
              }}
              name="LastName"
              value={lname}
              onChange={(e) => {
                const textInput = e.target.value;
                // Use a regular expression to check for alphabetic characters only
                const validTextInput = textInput.replace(/[^a-zA-Z]/g, '');
                setLname(validTextInput);
              }}
              onKeyDown={(e) => {
                // Prevent typing numbers and special characters by capturing keydown events
                if (!/^[a-zA-Z]*$/.test(e.key)) {
                  e.preventDefault();
                }
              }}
            />
          </Grid>
          <Grid item xs={6} sx={{ padding: '0px 5px' }}>
            <InputLabel id="demo-simple-select-label"> {i18?.ACCOUNTSTITLE?.PHONE_CODE || "Phone Code"}</InputLabel>
            <FormControl disabled fullWidth>
              <Select
                labelId="demo-simple-select-label"
                id="demo-simple-select"
                sx={{
                  margin: '10px 0px',
                  width: '100%',
                  '& .MuiInputBase-input.MuiOutlinedInput-input': {
                    padding: '10.5px 14px'
                  }
                }}
                value={phoneCodes}
                onChange={handleCountryChange}
                MenuProps={MenuProps}
              >
                {CountryCode.map((data) => (
                  <MenuItem key={data.code} value={data.dial_code}>{data.name} &nbsp;&nbsp; {data.dial_code}</MenuItem>
                ))}
              </Select>
            </FormControl>
          </Grid>
          <Grid item xs={6} sx={{ padding: '0px 5px' }}>
            {getPhoneNumberInput()}
          </Grid>
          <Grid item xs={6} sx={{ padding: '0px 5px' }}>
            <InputLabel id="demo-simple-select-label"> {i18?.ACCOUNTSTITLE?.DATE_OF_BIRTH || "Date Of Birth"}</InputLabel>
            <LocalizationProvider dateAdapter={AdapterDayjs} adapterLocale="en-gb">
              <DemoContainer components={['DatePicker']}>
                <DatePicker
                  sx={{
                    margin: '10px 0px',
                    width: '100%',
                    '& .MuiInputBase-input.MuiOutlinedInput-input': {
                      padding: '10.5px 14px'
                    }
                  }}
                  value={details?.dob ? dayjs(details?.dob) : null}
                  maxDate={getMaxDate()}
                  onChange={handleDateChange}
                />
              </DemoContainer>
            </LocalizationProvider>
            {!isAbove18 && <p style={{ color: 'red' }}>Age must be above 18</p>}
          </Grid>
          <Grid item xs={6} sx={{ padding: '0px 5px' }}>
            <InputLabel id="demo-simple-select-label">{i18?.ACCOUNTSTITLE?.GENDER || "Gender"}</InputLabel>
            <FormControl fullWidth >
              <Select
                labelId="demo-simple-select-label"
                id="demo-simple-select"
                sx={{
                  margin: '10px 0px',
                  width: '100%',
                  '& .MuiInputBase-input.MuiOutlinedInput-input': {
                    padding: '10.5px 14px'
                  }
                }}
                value={genders}
                onChange={(e) => setGenders(e.target.value)}
                renderValue={(selected) => {
                  if (selected === '') {
                    return <em>{genders}</em>;
                  }
                  return selected;
                }}
              >
                <MenuItem value="Male">Male</MenuItem>
                <MenuItem value="Female">Female</MenuItem>
                <MenuItem value="Other">Other</MenuItem>
              </Select>
            </FormControl>
          </Grid>
          <Grid item xs={6} sx={{ padding: '0px 5px' }}>
            <InputField
              label={i18?.ACCOUNTSTITLE?.EMAIL || "Email"}
              sx={{
                margin: '10px 0px',
                width: '100%',
                '& .MuiInputBase-input.MuiOutlinedInput-input': {
                  padding: '10.5px 14px'
                }
              }}
              name="Email"
              error={!!emailError}
              helperText={emailError}
              value={eMails ? replaceStarsInEmailAddress(eMails, "1", details?.email) : ""}
              onChange={handleMailChange}
              disabled
            />
          </Grid>
          <Grid item xs={6} sx={{ padding: '0px 5px' }}>
            {/* <div>
            </div> */}
          </Grid>
          <Grid item xs={6} sx={{ padding: '10px 5px' }}>
            <InputLabel id="demo-simple-select-label" sx={{ paddingBottom: "8px" }}> {i18?.ACCOUNTSTITLE?.PROFILE_PIC || "Profile Pic"}</InputLabel>
            <ImageUpload value={images} onChange={handleUploadedFile} />
          </Grid>
        </Grid>
        <Divider sx={{ backgroundColor: "#333", margin: "40px 0px", width: "100%" }} />
        <div style={{ display: 'flex', gap: '30px', justifyContent: 'end' }}>
        
          <Button variant="contained" disabled={isDisableButton} onClick={() => EditUserApi(id)}>
            {i18?.ACCOUNTSTITLE?.UPDATE || "Update"}
          </Button>
          <>
            <Grid>
              {!details.isActive ? (
                <Button color="success" variant="contained" onClick={() => userActive(id, true)}>
                  {i18?.ACCOUNTSTITLE?.ACTIVE || "Active"}
                </Button>
              ) : (
                <Button color="error" variant="contained" onClick={() => userActive(id, false)}>
                  {i18?.ACCOUNTSTITLE?.INACTIVE || "InActive"}
                </Button>
              )}
            </Grid>
            <Grid>
              {!details.verified ? (
                <Button color="success" variant="contained" onClick={() => userVerify(id, true)}>
                  {i18?.ACCOUNTSTITLE?.VERIFY || "Verify"}
                </Button>
              ) : (
                <Button color="warning" variant="contained" onClick={() => userVerify(id, false)}>
                  {i18?.ACCOUNTSTITLE?.DENY || "Deny"}
                </Button>
              )}
            </Grid>
          </>
        </div>
      </Card>

      {documentsMode === '1' && <Card sx={{ padding: '20px 10px', margin: '10px 0px' }}>
        <Grid container sx={{ borderBottom: '1px solid #dbe0e4', padding: '10px 0px' }}>
          <Grid container item justifyContent="space-between" alignItems="center" sx={{ marginRight: '10px' }}>
            <Typography variant="h6" gutterBottom sx={{ margin: '0px 0px 0px 10px', paddingBottom: '0px' }}>
              {/* {i18?.ACCOUNTSTITLE?.DOCUMENTS || "Documents"} */}
              {getTranslation('Documents')}
            </Typography>
          </Grid>
        </Grid>

        {documents.map((doc, index) => (
          <Accordion key={index} >
            <AccordionSummary expandIcon={<ExpandMoreIcon />}>
              <Box sx={{ display: "flex", justifyContent: "space-between", alignItems: "center", width: '100%' }}>
                <Box sx={{ display: "flex", alignItems: "center" }}>
                  <Typography>{doc.name}</Typography>
                  {doc?.status === "approved" && <Iconify icon={'fa-solid:check-circle'} sx={{ ml: 1 }} />}
                  {doc?.status === "pending" && <Iconify icon={'fa-solid:times-circle'} sx={{ ml: 1 }} />}
                  {doc?.status === "reject" && <Iconify icon={'fa-solid:exclamation-triangle'} sx={{ ml: 1 }} />}
                </Box>
                <IconButton onClick={(e) => handleMenuOpen(e, doc)} size="small">
                  <MoreVertIcon />
                </IconButton>
              </Box>
            </AccordionSummary>
            <AccordionDetails>
              <Box sx={{ display: "grid", gap: 2 }}>
                {doc?.fields?.map((fil, ind) => (
                  <Box key={ind} sx={{ display: "flex", justifyContent: "space-between", flexDirection: "row" }}>
                    <Typography>{fil.name}: </Typography>
                    {fil.value ? (
                      fil.indexName.includes('Image') ? (
                        <Link sx={{ cursor: "pointer" }} href={`${IMAGE_URL}${fil.value}`} target="_blank" rel="noopener">
                          {i18?.ACCOUNTSTITLE?.VIEW || "View"}
                        </Link>
                      ) : fil.indexName.includes('Date') ? (
                        <Typography>{DateFormat(fil.value)}</Typography>
                      ) : (
                        <Typography>{fil.value}</Typography>
                      )
                    ) : (
                      <Typography>{i18?.ACCOUNTSTITLE?.NO_DATA_AVAILABLE || "No data available"}</Typography>
                    )}
                  </Box>
                ))}
              </Box>
            </AccordionDetails>
          </Accordion>
        ))}

        <Menu
          anchorEl={anchorEl}
          open={Boolean(anchorEl)}
          onClose={handleMenuClose}
          MenuListProps={{ 'aria-labelledby': 'basic-button' }}
        >
          {<MenuItem onClick={() => handleActionDocuments()}>
            <Iconify icon={'eva:edit-fill'} sx={{ mr: 2 }} /> {i18?.ACCOUNTSTITLE?.UPDATE || "Update"}
          </MenuItem>}

          {selectedAccordion?.status !== "approved" && selectedAccordion?.status !== "needAction" && <MenuItem onClick={() => handleVerifyDocuments(id, selectedAccordion.indexName, "approved")}>
            <Iconify icon={'bi:check-circle-fill'} sx={{ mr: 2 }} /> {i18?.ACCOUNTSTITLE?.ACCEPT || "Accept"}
          </MenuItem>}
          {selectedAccordion?.status !== "reject" && selectedAccordion?.status !== "needAction" && <MenuItem onClick={() => handleVerifyDocuments(id, selectedAccordion.indexName, "reject")}>
            <Iconify icon={'bi:x-circle-fill'} sx={{ mr: 2 }} /> {i18?.ACCOUNTSTITLE?.REJECT || "Reject"}
          </MenuItem>}

        </Menu>
      </Card>}

      <Dialog open={openModal} onClose={handleModalClose}>
        <DialogTitle>{getTranslation(selectedAccordion?.name ? selectedAccordion?.name : '')}</DialogTitle>
        <DialogContent sx={{ display: "grid", gap: 2, paddingTop: 2 }}>
          <DialogContentText>
            {i18?.ACCOUNTSTITLE?.PROVIDE_DETAILS || "Please provide the following details"}:
          </DialogContentText>

          {selectedAccordion?.fields?.map((field, index) => (
            <Box key={index}>
              {field.indexName.includes('Image') && (
                <TextField
                  margin="dense"
                  label={getTranslation(field.name)}
                  InputLabelProps={{
                    shrink: true
                  }}
                  type="file"
                  fullWidth
                  onChange={(e) => handleFileChange(e, field.indexName)}
                />
              )}

              {field.indexName.includes('Date') && (
                <LocalizationProvider dateAdapter={AdapterDayjs}>
                  <DatePicker
                    label={getTranslation(field.name)}
                    value={date}
                    sx={{ width: '100%' }}
                    onChange={(newValue) => handleDocumentDateChange(newValue, field.indexName)}
                    renderInput={(params) => (
                      <TextField {...params} fullWidth />
                    )}
                    disablePast
                  />
                </LocalizationProvider>
              )}

              {!field.indexName.includes('Image') && !field.indexName.includes('Date') && (
                <TextField
                  margin="dense"
                  label={getTranslation(field.name)}
                  type="text"
                  fullWidth
                  value={textValues[field.indexName] || ''}
                  onChange={(e) => handleInputChange(e, field.indexName)}
                />
              )}
            </Box>
          ))}
        </DialogContent>

        <DialogActions>
          <Button onClick={handleModalClose} color="error">
            {i18?.ACCOUNTSTITLE?.Cancel || "Cancel"}
          </Button>
          <Button onClick={() => handleModalSave(selectedAccordion.indexName)} color="primary">
            {i18?.ACCOUNTSTITLE?.SAVE || "Save"}
          </Button>
        </DialogActions>
      </Dialog>
    </>
  );
}

export default EditUser;
